fn fibonacci(n: usize) -> Vec<i32> {
    // We assume n >= 2 and that F(n-1) fits in i32.
    let mut ret = Vec::with_capacity(n);
    ret.push(0);
    ret.push(1);
    for i in 2..n {
        // Safe to add without overflow under the problem assumptions
        let next = ret[i - 1] + ret[i - 2];
        ret.push(next);
    }
    ret
}